import{_ as r,l as n,o as e,c as i,v as t,p,x as o,d as s,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"税务感知组合","description":"","frontmatter":{"title":"税务感知组合","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/tax-aware-portfolio.md","filePath":"quant/tax-aware-portfolio.md","lastUpdated":1789023840000}'),h={name:"quant/tax-aware-portfolio.md"};function m(A,a,c,u,B,_){const l=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="税务感知组合" tabindex="-1">税务感知组合 <a class="header-anchor" href="#税务感知组合" aria-label="Permalink to &quot;税务感知组合&quot;">​</a></h1><div class="epigraph"><p>实现损失、推迟收益、避免洗售，使最优交易依赖于税基批次；不计税的 DP 会在应税账户里系统性过交易。</p><footer>—— Dammon, Spatt and Zhang, Optimal Asset Location and Allocation with Taxable and Tax-Deferred Saving, Journal of Finance, 2004</footer></div><p><a href="/quant/robust-portfolio-opt">上一课</a>把稳健组合写成 maximin：半径是偏好，机制是最坏而不是后验平均，不能替代宏观压力情景。缺口是应税账户：DP 与 GP 默认税后等于税前，同一只股票不同买入价，卖哪一批改变当期税，批次成为状态。本课钉税务感知组合：资产位置、损失收割与再平衡的冲突。不重讲椭圆不确定集。不写避税操作清单；后课多期风险预算默认 lot 与洗售窗口已经进状态，而不是事后扣税。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>稳健优化收缩的是最坏 \\(\\mu\\)，应税账户的状态却是批次。再平衡要卖赢的、买输的，正好实现资本利得。最优往往是：尽量用新现金流与应税损失来调暴露，而不是卖长期高税基仓。问题是状态爆炸：每只证券多个 lot、长期/短期税率、洗售窗口。完全 DP 不可行，实务用启发式：先收割损失、用期货/ETF 维持暴露、避免 30 天内买回同一证券（美国洗售；其他法域规则不同）。</p><p>资产位置：高期望税负的资产放在递延账户，市政债等放在应税账户。Dammon–Spatt–Zhang 指出位置与配置互相依赖，不能先 Markowitz 再随便塞账户。</p><h3 id="税-alpha-不是市场-alpha" tabindex="-1">税 alpha 不是市场 alpha <a class="header-anchor" href="#税-alpha-不是市场-alpha" aria-label="Permalink to &quot;税 alpha 不是市场 alpha&quot;">​</a></h3><p>损失收割的价值来自期权式的凸性（损失立即用、收益推迟），依赖税率、波动与现金流。把它当成股票 alpha 会在回测里制造无容量的「税务因子」，并在税率改革时消失。应单独记账。</p><p><span class="marginnote">不同法域：美国 wash sale、欧洲某些国家的持股期、中国个人股息税与资本利得的现行规则不同。引擎要参数化，不要写死 IRS 条款当全球真理。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>账户分层：应税、递延、免税。优化：在暴露约束下最小化当期税 + 未来税的近似（对未实现收益打折）。Lot 选择：HIFO 或优化选择以实现损失。再平衡带加宽，与费用课的无交易带叠加。对照：不计税再平衡 vs 税务感知的税后终值，用同一税则模拟。</p><p>GP 的 \\(\\Lambda\\) 在应税账户应加上边际税率带来的有效冲击。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>税使卖出有不对称成本：实现收益付税，实现损失获抵扣（有限制）。于是无交易带在盈利仓更宽、在亏损仓更窄（甚至主动卖）。位置则是边际税率不同的「不同费用」账户之间的配置。与 Merton 的 \\(\\gamma\\) 相比，税是另一个状态依赖的费用函数。</p>',14)),(e(),p(E,null,{default:o(()=>[d(l,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20Lots%5B%22%E7%A8%8E%E5%9F%BA%E6%89%B9%E6%AC%A1%22%5D%20--%3E%20Sell%5B%22%E5%8D%96%E5%93%AA%E4%B8%80%E6%89%B9%E5%86%B3%E5%AE%9A%E5%BD%93%E6%9C%9F%E7%A8%8E%22%5D%0A%20%20Loc%5B%22%E5%BA%94%E7%A8%8E%E5%AF%B9%E9%80%92%E5%BB%B6%E4%BD%8D%E7%BD%AE%22%5D%20--%3E%20Alloc%5B%22%E9%85%8D%E7%BD%AE%E4%B8%8E%E4%BD%8D%E7%BD%AE%E8%81%94%E5%90%88%22%5D%0A%20%20Wash%5B%22%E6%B4%97%E5%94%AE%E7%AA%97%E5%8F%A3%22%5D%20--%3E%20Band%5B%22%E5%86%8D%E5%B9%B3%E8%A1%A1%E5%B8%A6%E5%8A%A0%E5%AE%BD%22%5D%0A%20%20Sell%20--%3E%20Band%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>税法变更是模型风险。递延账户的提前支取罚金、最低分配，使「递延永远更好」不成立。用衍生品维持暴露可能被重定性。本课不提供规避申报或隐瞒税基的方法。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>应税账户的状态含 lot；不计税的最优再平衡会过交易。</li><li>配置与位置应联合；税 alpha 单独记账。</li><li>有效冲击含税，无交易带不对称。</li><li>出处：Dammon, Spatt and Zhang, <em>Journal of Finance</em>, 2004。</li></ul>',4))])}const x=r(h,[["render",m]]);export{D as __pageData,x as default};
